('eco-park', 'Eco-Park', 'park', 13.01406, 77.464504, 1058, 'Westhollow. Wind turbines, solar field, a pond and a lookout tower.'),
('grand-theatre', 'Meridian Grand Theatre', 'theatre', 12.997958, 77.51181, 900, 'Downtown, off East Avenue.'),
